const config = $('Business Config').first().json;
let contentPillars;
try { contentPillars = JSON.parse(config.contentPillars); }
catch (e) { contentPillars = ['Slow replies to patient enquiries cost appointments', 'Agentic AI workflows that follow up on enquiries that did not book', 'Agentic AI workflows on WhatsApp for the dental front desk']; }
let ctaKeywords;
try { ctaKeywords = JSON.parse(config.ctaKeywords); }
catch (e) { ctaKeywords = ['BOOK', 'FAST', 'LEADS', 'SMART', 'GROW']; }
const today = $now.toFormat('yyyy-MM-dd');
const rows = $input.all().map(i => {
  const o = {};
  Object.keys(i.json || {}).forEach(k => { o[k.trim()] = i.json[k]; });
  return o;
}).filter(r => r.topic || r.date);
const todayPostCount = rows.filter(r => String(r.date || '').slice(0, 10) === today && String(r.status || '').trim().toLowerCase() === 'published').length;
const maxPosts = parseInt(config.maxPostsPerDay) || 1;
if (todayPostCount >= maxPosts) {
  return [{ json: { ...config, canPost: false, todayPostCount, maxPostsPerDay: maxPosts } }];
}
const sorted = rows.filter(r => r.topic).sort((a, b) => new Date(b.timestamp || b.date) - new Date(a.timestamp || a.date));
const recentTopics = sorted.slice(0, 7).map(r => r.topic);
let availableTopics = contentPillars.filter(t => !recentTopics.includes(t));
if (availableTopics.length === 0) availableTopics = contentPillars;
const selectedTopic = availableTopics[Math.floor(Math.random() * availableTopics.length)];
const angles = [
  'Open with a short scene: a patient messages the clinic and nobody replies in time',
  'Unpopular opinion: your clinic may not need more leads, it needs a better process for the enquiries it already has',
  'Give 3 signs or 3 practical actions, one per scene',
  'Bust a common myth about AI in a dental clinic',
  'Show how an agentic AI workflow handles one enquiry end to end: reply, follow-up, booking, reminder',
  'Ask a thought-provoking question and answer it scene by scene',
  'Describe what you would hand to agentic AI workflows first if you owned the clinic'
];
const selectedAngle = angles[Math.floor(Math.random() * angles.length)];
const ctaKeyword = ctaKeywords[Math.floor(Math.random() * ctaKeywords.length)];
const h = $now.hour;
return [{ json: { ...config, canPost: true, todayPostCount, maxPostsPerDay: maxPosts, selectedTopic, selectedAngle, ctaKeyword, dayName: $now.toFormat('cccc'), timeSlot: h < 12 ? 'morning' : h < 17 ? 'afternoon' : 'evening', generatedAt: $now.toISO() } }];

