const raw = $input.first().json.output[0].content[0].text;
const fence = String.fromCharCode(96).repeat(3);
const cleaned = String(raw).split(fence + 'json').join('').split(fence).join('').trim();
let data;
try { data = JSON.parse(cleaned); }
catch (e) { throw new Error('The script came back as invalid JSON: ' + cleaned.slice(0, 200)); }
const scenes = (data.scenes || []).slice(0, 5);
if (scenes.length < 5) throw new Error('The script has fewer than 5 scenes.');
const clean = (s) => String(s || '').split('*').join('').trim();
const banned = ['n8n', 'zapier', 'openai', 'chatgpt', 'gpt'];
const everything = (clean(data.title) + ' ' + clean(data.description) + ' ' + scenes.map(s => clean(s.line)).join(' ')).toLowerCase();
banned.forEach(w => { if (everything.includes(w)) throw new Error('The script names a tool: ' + w); });
let title = clean(data.title).split('#').join('').trim();
if (title.length > 95) title = title.slice(0, 95).trim();
let description = clean(data.description);
if (!description.includes('#Shorts')) description = description + '\n\n#Shorts #AgenticAI #AIAutomation #DentalClinic';
const tags = (Array.isArray(data.tags) ? data.tags : []).map(t => clean(t).split(',').join(' ')).filter(Boolean).slice(0, 8).join(',');
const suffix = ', photorealistic, vertical composition, no text, no letters, no logos, no recognisable real people';
const elements = scenes.map((s, i) => ({
  type: 'composition',
  track: 1,
  elements: [
    {
      type: 'image',
      provider: 'openai model=gpt-image-1-mini size=1024x1536',
      source: clean(s.image) + suffix,
      fit: 'cover',
      clip: true,
      animations: [{ easing: 'linear', type: 'scale', scope: 'element', start_scale: '120%', end_scale: '100%', fade: false }]
    },
    { type: 'audio', name: 'Voice' + (i + 1), provider: "openai model=tts-1 voice='alloy'", source: clean(s.line) },
    {
      type: 'text',
      transcript_source: 'Voice' + (i + 1),
      transcript_effect: 'highlight',
      x: '50%',
      y: '78%',
      width: '86%',
      fill_color: '#ffffff',
      stroke_color: '#000000',
      stroke_width: '1.2 vmin',
      font_size: '6.5 vmin',
      font_weight: '800',
      text: 'placeholder'
    }
  ]
}));
return [{ json: {
  renderBody: { render_scale: 1, source: { output_format: 'mp4', width: 720, height: 1280, frame_rate: 25, elements } },
  title,
  description,
  tags,
  imagePrompts: scenes.map(s => clean(s.image)).join(' | '),
  voiceover: scenes.map(s => clean(s.line)).join(' ')
} }];
